101→	async function handleTaskUpdated() {
102→		// Reload the task detail to reflect changes
103→		if (panelTask) {
104→			try {
105→				panelTask = await fetchTask(panelTask._ulid);
106→			} catch (err) {
107→				console.error('Error reloading task:', err);
108→			}
109→		}
110→		// Reload the task list to reflect status changes
111→		loadTasks();
112→	}
