   111→	function handleCardClick(task: TaskSummary) {
   112→		selectedTaskRef = task._ulid;
   113→		modalOpen = true;
   114→	}
   115→
   116→	function handleTaskUpdated() {
   117→		loadBoard();
   118→	}
   119→
   120→	// AC: @ui-task-board ac-5 — WebSocket real-time updates
   121→	function handleTaskUpdate(event: BroadcastEvent) {
   122→		loadBoard();
   123→	}
   124→
   125→	// AC: @ui-task-board ac-4 — Refresh agent status on agent events
   126→	function handleAgentUpdate(event: BroadcastEvent) {
   127→		// AC: @ui-task-board ac-4 — Buffer text chunks into complete lines
   128→		if (event.event === 'agent_text_chunk' && event.data?.session_id && event.data?.text) {
   129→			const sessionId = event.data.session_id as string;
   130→			const text = event.data.text as string;
   131→			const current = sessionStates[sessionId] ?? createSessionState();
   132→			sessionStates[sessionId] = processTextChunk(current, text);
   133→			return;
   134→		}
   135→
   136→		// Invocation lifecycle events — refresh status and clean up stale state
   137→		fetchAgentStatus()
   138→			.then((status) => {
   139→				agentStatus = status;
   140→				// Clean up session states for sessions no longer active
   141→				const activeSessions = new Set(
   142→					status.active_invocations.map((inv) => inv.session_id)
   143→				);
   144→				for (const sessionId of Object.keys(sessionStates)) {
   145→					if (!activeSessions.has(sessionId)) {
   146→						delete sessionStates[sessionId];
   147→					}
   148→				}
   149→			})
   150→			.catch(() => {});
   151→	}
   152→
   153→	// Polling for agent elapsed time updates
   154→	let agentPollTimer: ReturnType<typeof setInterval> | undefined;
   155→
   156→	onMount(() => {
   157→		// AC: @ui-task-board ac-5 — Subscribe to task and agent updates
   158→		subscribe(['tasks', 'agents']);
   159→		on('tasks', handleTaskUpdate);
   160→		on('agents', handleAgentUpdate);
   161→
   162→		// Poll agent status every 5s for elapsed time updates
   163→		agentPollTimer = setInterval(() => {
   164→			fetchAgentStatus()
   165→				.then((status) => {
   166→					agentStatus = status;
   167→				})
   168→				.catch(() => {});
   169→		}, 5000);
   170→	});
   171→
   172→	onDestroy(() => {
   173→		off('tasks', handleTaskUpdate);
   174→		off('agents', handleAgentUpdate);
   175→		unsubscribe(['tasks', 'agents']);
   176→		if (agentPollTimer) clearInterval(agentPollTimer);
   177→	});
   178→</script>
   179→
   180→<div class="flex flex-col h-full min-w-0">
