   185→			{#if !loading && columns.length > 0}
   186→				{@const visibleCount = columns.reduce((sum, col) => sum + col.tasks.length, 0)}
   187→				<p class="text-sm text-muted-foreground">{visibleCount} tasks</p>
   188→			{/if}
   189→		</div>
   190→
   191→		<!-- View toggle: Board / List -->
   192→		<div class="flex items-center gap-1 border rounded-lg p-0.5">
   193→			<Button
   194→				variant="ghost"
   195→				size="icon-sm"
   196→				class="bg-accent"
   197→				title="Board view"
   198→				aria-pressed="true"
   199→			>
   200→				<LayoutGrid class="size-4" />
   201→			</Button>
   202→			<a href="{base}/tasks" title="List view">
   203→				<Button variant="ghost" size="icon-sm" aria-pressed="false">
   204→					<List class="size-4" />
   205→				</Button>
   206→			</a>
   207→		</div>
