   213→			{error}
   214→		</div>
   215→	{/if}
   216→
   217→	<!-- Loading skeleton -->
   218→	{#if loading}
   219→		<BoardSkeleton />
   220→	{:else if tasks.length === 0}
   221→		<!-- Empty state -->
   222→		<div class="flex flex-col items-center justify-center flex-1 py-16" data-testid="board-empty">
   223→			<LayoutGrid class="size-12 text-muted-foreground/30 mb-4" />
   224→			<h2 class="text-lg font-medium text-muted-foreground mb-1">No tasks yet</h2>
   225→			<p class="text-sm text-muted-foreground">
   226→				Create tasks using <code class="bg-muted px-1 rounded text-xs">kspec task add</code>
   227→			</p>
   228→		</div>
   229→	{:else}
   230→		<!-- AC: @ui-task-board ac-4 — Active Fleet Row -->
   231→		<div class="px-6 pt-4">
   232→			<ActiveFleetRow status={agentStatus} outputLines={agentOutputLines} {taskTitles} />
   233→		</div>
   234→
   235→		<!-- AC: @ui-task-board ac-1 — Kanban Columns -->
