     1→<!--
     2→  AC: @ui-task-board ac-3 — Task detail modal with full task info.
     3→  AC: @ui-task-board ac-6 — Action buttons: Start, Submit, Complete, Block, Add Note.
     4→
     5→  Kanban board task detail dialog. Wraps TaskDetailContent in a Dialog overlay.
     6→-->
     7→<script lang="ts">
     8→	import type { TaskDetail } from '@kynetic-ai/shared';
     9→	import { fetchTask } from '$lib/api';
    10→	import * as Dialog from '$lib/components/ui/dialog';
    11→	import TaskDetailContent from './TaskDetailContent.svelte';
    12→
    13→	let {
    14→		open = $bindable(false),
    15→		taskRef = $bindable<string | null>(null),
    16→		onTaskUpdated
    17→	}: {
    18→		open?: boolean;
    19→		taskRef?: string | null;
    20→		onTaskUpdated?: () => void;
    21→	} = $props();
    22→
    23→	let task = $state<TaskDetail | null>(null);
    24→	let loading = $state(false);
    25→	let error = $state('');
    26→
    27→	$effect(() => {
    28→		if (open && taskRef) {
    29→			loadTask(taskRef);
    30→		} else if (!open) {
    31→			task = null;
    32→			error = '';
    33→		}
    34→	});
    35→
    36→	async function loadTask(ref: string) {
    37→		loading = true;
    38→		error = '';
    39→		try {
    40→			task = await fetchTask(ref);
    41→		} catch (err) {
    42→			error = err instanceof Error ? err.message : 'Failed to load task';
    43→		} finally {
    44→			loading = false;
    45→		}
    46→	}
    47→
    48→	async function handleTaskUpdated() {
    49→		if (task) {
    50→			task = await fetchTask(task._ulid);
    51→		}
    52→		onTaskUpdated?.();
    53→	}
    54→
    55→	let slug = $derived(task?.slugs?.[0] ?? task?._ulid?.slice(0, 8) ?? '');
    56→</script>
    57→
    58→<Dialog.Root bind:open>
    59→	<Dialog.Content class="max-w-2xl max-h-[85vh] overflow-y-auto" data-testid="task-detail-modal">
    60→		{#if task && !loading && !error}
    61→			<Dialog.Header>
    62→				<Dialog.Title data-testid="task-detail-title">{task.title}</Dialog.Title>
    63→				<Dialog.Description>
    64→					<span class="font-mono text-xs">@{slug}</span>
    65→				</Dialog.Description>
    66→			</Dialog.Header>
    67→		{/if}
    68→
    69→		<TaskDetailContent
    70→			{task}
    71→			{loading}
    72→			{error}
    73→			onTaskUpdated={handleTaskUpdated}
    74→		/>
    75→	</Dialog.Content>
    76→</Dialog.Root>
    77→
